const canvas=document.getElementById('gameCanvas');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9dcea2); scene.fog=new THREE.Fog(0x9dcea2,18,42);
const camera=new THREE.PerspectiveCamera(42,innerWidth/innerHeight,.1,100); camera.position.set(0,8.7,11); camera.lookAt(0,0,0);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,2)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
scene.add(new THREE.HemisphereLight(0xdfffe4,0x457252,2.1)); const sun=new THREE.DirectionalLight(0xfff5d6,2.4);sun.position.set(-8,14,7);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);scene.add(sun);
const meadow=new THREE.Group();scene.add(meadow);
function mat(c){return new THREE.MeshStandardMaterial({color:c,roughness:.9})} const green=mat(0x75b879), darkGreen=mat(0x367e5b), bark=mat(0x8e6846), leaf=mat(0x4d9866), flower=mat(0xf5df84);
const ground=new THREE.Mesh(new THREE.CylinderGeometry(23,23,.5,64),mat(0x6dad76));ground.position.y=-.3;ground.receiveShadow=true;meadow.add(ground);
// paths
const path=new THREE.Mesh(new THREE.CircleGeometry(7.5,48),mat(0xb9a777));path.rotation.x=-Math.PI/2;path.position.y=-.03;path.scale.set(1.7,.58,1);meadow.add(path);
const path2=new THREE.Mesh(new THREE.CircleGeometry(5,48),mat(0xc5b783));path2.rotation.x=-Math.PI/2;path2.position.set(-4,.0,2);path2.scale.set(.7,1.8,1);meadow.add(path2);
function tree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(s);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.16,.27,1.7,7),bark);trunk.position.y=.7;trunk.castShadow=true;g.add(trunk);for(let i=0;i<3;i++){const crown=new THREE.Mesh(new THREE.IcosahedronGeometry(.8,1),leaf);crown.position.set((i-1)*.35,1.65+(i%2)*.3,(i%2)*.25);crown.castShadow=true;g.add(crown)}meadow.add(g)}
[[-7,-4,1.1],[-9,2,1.2],[7,-3,1.25],[8,4,1.1],[-3,7,1],[4,7,1.25],[10,0,.8]].forEach(v=>tree(...v));
function flowerPatch(x,z){for(let i=0;i<5;i++){const f=new THREE.Mesh(new THREE.SphereGeometry(.09,6,6),flower);f.position.set(x+(Math.random()-.5)*1.3,.15,z+(Math.random()-.5)*1.1);f.scale.y=1.8;meadow.add(f)}} flowerPatch(-5,-1);flowerPatch(5,1);flowerPatch(-1,5);
// player companion creature
const player=new THREE.Group();player.position.set(0,.15,3);scene.add(player);const pbody=new THREE.Mesh(new THREE.SphereGeometry(.48,16,12),mat(0xf0b766));pbody.scale.set(1,1.1,.9);pbody.castShadow=true;player.add(pbody);const belly=new THREE.Mesh(new THREE.SphereGeometry(.32,14,10),mat(0xffdfa0));belly.position.set(0,-.02,.4);belly.scale.set(1,.9,.35);player.add(belly);function eye(x){const e=new THREE.Mesh(new THREE.SphereGeometry(.055,8,8),mat(0x20382d));e.position.set(x,.22,.42);player.add(e)}eye(-.16);eye(.16);const earMat=mat(0x5c9d6f);[-.36,.36].forEach(x=>{const e=new THREE.Mesh(new THREE.ConeGeometry(.15,.43,8),earMat);e.position.set(x,.55,0);e.rotation.z=x>0?-.3:.3;player.add(e)});
// wild creature in clearing
const wild=new THREE.Group();wild.position.set(2.55,.18,-.75);wild.userData={name:'Leaflet'};scene.add(wild);const wbody=new THREE.Mesh(new THREE.SphereGeometry(.55,18,14),mat(0x9edb73));wbody.scale.set(1.18,.88,.92);wbody.castShadow=true;wild.add(wbody);const wface=new THREE.Mesh(new THREE.SphereGeometry(.35,16,12),mat(0xd9f19c));wface.position.set(0,.02,.44);wface.scale.set(1,.9,.3);wild.add(wface);[-.15,.15].forEach(x=>{const e=new THREE.Mesh(new THREE.SphereGeometry(.055,8,8),mat(0x264b36));e.position.set(x,.18,.54);wild.add(e)});const leafTop=new THREE.Mesh(new THREE.ConeGeometry(.33,.9,5),mat(0x4a9d65));leafTop.position.y=.68;leafTop.rotation.z=.12;wild.add(leafTop);wild.traverse(o=>{if(o.isMesh)o.castShadow=true});
// distant tiny critters
for(let i=0;i<4;i++){const c=new THREE.Mesh(new THREE.SphereGeometry(.18,10,8),mat(i%2?0xa9d2e3:0xf2c67b));c.position.set(-4+i*2.2,.15,-3.3-(i%2)*1.3);c.castShadow=true;scene.add(c)}
const ray=new THREE.Raycaster(), pointer=new THREE.Vector2();let moving={x:0,y:0};let keys={};
function showEncounter(){document.getElementById('encounter').classList.remove('hidden');document.getElementById('encounterName').textContent='Leaflet';document.getElementById('encounterText').textContent='A tiny sprout spirit watches you with bright, curious eyes.'}
canvas.addEventListener('pointerdown',e=>{pointer.x=e.clientX/innerWidth*2-1;pointer.y=-(e.clientY/innerHeight)*2+1;ray.setFromCamera(pointer,camera);if(ray.intersectObject(wild,true).length)showEncounter()});
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2100)}
document.getElementById('captureBtn').onclick=showEncounter;document.getElementById('closeEncounter').onclick=()=>document.getElementById('encounter').classList.add('hidden');document.getElementById('waveBtn').onclick=()=>{document.getElementById('encounter').classList.add('hidden');toast('Leaflet chirps happily!');};document.getElementById('tossBtn').onclick=()=>{document.getElementById('encounter').classList.add('hidden');document.getElementById('questCount').textContent='2';toast('Leaflet joined your party ✦');wild.visible=false};
document.getElementById('bagBtn').onclick=()=>{document.getElementById('modal').classList.remove('hidden');document.getElementById('modalContent').innerHTML='<h2>Your Field Bag</h2><p>Everything you need for a day out in the meadow.</p><div class="collection"><div>✧<small>Lumi Ball × 8</small></div><div>◈<small>Berry × 4</small></div><div>✦<small>Leaflet</small></div></div>'};document.getElementById('mapBtn').onclick=()=>toast('You are here · Meadow Loop');document.getElementById('closeModal').onclick=()=>document.getElementById('modal').classList.add('hidden');document.getElementById('soundBtn').onclick=e=>{e.currentTarget.textContent=e.currentTarget.textContent==='◔'?'◑':'◔';toast('Sound settings updated')};
window.addEventListener('keydown',e=>keys[e.key.toLowerCase()]=true);window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
const joystick=document.getElementById('joystick');let joyActive=false;joystick.addEventListener('pointerdown',e=>{joyActive=true;joystick.setPointerCapture(e.pointerId);moveJoy(e)});joystick.addEventListener('pointermove',e=>{if(joyActive)moveJoy(e)});joystick.addEventListener('pointerup',()=>{joyActive=false;moving={x:0,y:0};document.querySelector('.joy-knob').style.transform='translate(0,0)'});function moveJoy(e){const r=joystick.getBoundingClientRect(),x=Math.max(-25,Math.min(25,e.clientX-(r.left+38))),y=Math.max(-25,Math.min(25,e.clientY-(r.top+38)));moving={x:x/25,y:y/25};document.querySelector('.joy-knob').style.transform=`translate(${x}px,${y}px)`}
let clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);const t=clock.getElapsedTime();const dx=(keys.a?-1:0)+(keys.d?1:0)+moving.x,dz=(keys.w?-1:0)+(keys.s?1:0)+moving.y;player.position.x+=dx*.035;player.position.z+=dz*.035;player.position.x=Math.max(-8,Math.min(8,player.position.x));player.position.z=Math.max(-4,Math.min(7,player.position.z));player.rotation.y=dx?Math.atan2(dx,dz):player.rotation.y;player.position.y=.15+Math.sin(t*3)*.035;wild.position.y=.18+Math.sin(t*2.2)*.08;wild.rotation.y=Math.sin(t*.7)*.12;renderer.render(scene,camera)}animate();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

